CREATE TABLE IF NOT EXISTS sections (id text PRIMARY KEY, title text NOT NULL, content text NOT NULL, url text NOT NULL, language text NOT NULL CHECK(language IN ('en','am')), course_id text, keywords jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS tickets (id uuid PRIMARY KEY, token_hash text NOT NULL, language text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','active','resolved')), kind text NOT NULL DEFAULT 'learning', conversation jsonb NOT NULL DEFAULT '[]', context jsonb, screenshot text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tutor_messages (id bigserial PRIMARY KEY, ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tutor_messages_ticket_idx ON tutor_messages(ticket_id,id);
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY, token_hash text NOT NULL, channel text NOT NULL CHECK(channel IN ('telegram','sms')), destination text NOT NULL, language text NOT NULL CHECK(language IN ('en','am')), keywords text NOT NULL DEFAULT '', verified boolean NOT NULL DEFAULT false, verification_hash text, verification_expires timestamptz, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(channel,destination));
CREATE TABLE IF NOT EXISTS alert_deliveries (subscription_id uuid REFERENCES subscriptions(id) ON DELETE CASCADE, job_id text REFERENCES jobs(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, retry_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, PRIMARY KEY(subscription_id,job_id));
CREATE TABLE IF NOT EXISTS share_sessions (id uuid PRIMARY KEY, ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS share_signals (id bigserial PRIMARY KEY, session_id uuid NOT NULL REFERENCES share_sessions(id) ON DELETE CASCADE, sender text NOT NULL CHECK(sender IN ('learner','tutor')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS share_signals_session_idx ON share_signals(session_id,id);
CREATE TABLE IF NOT EXISTS webhooks (id uuid PRIMARY KEY, url text NOT NULL UNIQUE, secret text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id uuid PRIMARY KEY, webhook_id uuid NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, delivered_at timestamptz, retry_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz);
